package org.apache.parquet.filter2;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

public class IncrementallyUpdatedFilterPredicateGeneratorRunTests {

  @Test
  void runWritesCompleteGeneratedBuilderSource() throws IOException {
    Path output = Files.createTempFile("incrementally-updated-filter-predicate-builder", ".java");
    try {
      new org.apache.parquet.filter2.IncrementallyUpdatedFilterPredicateGenerator(output.toFile()).run();

      String source = Files.readString(output, StandardCharsets.UTF_8);

      assertTrue(source.startsWith("package org.apache.parquet.filter2.recordlevel;"),
          "Generated source must declare the record-level package");
      assertTrue(source.contains(
          "public class IncrementallyUpdatedFilterPredicateBuilder "
              + "extends IncrementallyUpdatedFilterPredicateBuilderBase"),
          "Generated source must declare the expected builder class");
      assertTrue(source.contains(
          "public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves)"),
          "Generated source must provide the leaves constructor");

      assertContainsAll(source,
          "visit(Eq<T> pred)",
          "visit(NotEq<T> pred)",
          "visit(In<T> pred)",
          "visit(NotIn<T> pred)",
          "visit(Contains<T> contains)",
          "visit(Lt<T> pred)",
          "visit(LtEq<T> pred)",
          "visit(Gt<T> pred)",
          "visit(GtEq<T> pred)",
          "visit(UserDefined<T, U> pred)",
          "visit(LogicalNotUserDefined<T, U> notPred)");

      assertContainsAll(source,
          "clazz.equals(Integer.class)",
          "clazz.equals(Long.class)",
          "clazz.equals(Boolean.class)",
          "clazz.equals(Float.class)",
          "clazz.equals(Double.class)",
          "clazz.equals(Binary.class)");

      assertContainsAll(source,
          "Operator < not supported for Boolean",
          "Operator <= not supported for Boolean",
          "Operator > not supported for Boolean",
          "Operator >= not supported for Boolean");

      assertTrue(source.contains("private static class ContainsSinglePredicate"),
          "Generated source must include single-value contains handling");
      assertTrue(source.contains("private static class ContainsAndPredicate"),
          "Generated source must include conjunction handling for contains");
      assertTrue(source.contains("private static class ContainsOrPredicate"),
          "Generated source must include disjunction handling for contains");
      assertTrue(source.contains("addValueInspector(columnPath, valueInspector);"),
          "Generated visitors must register their value inspectors");
      assertTrue(source.endsWith("}\n"),
          "Generated Java source must end with the builder class closing brace");
    } finally {
      Files.deleteIfExists(output);
    }
  }

  @Test
  void runProducesNonEmptySourceAndClosesTheOutputFile() throws IOException {
    Path output = Files.createTempFile("incrementally-updated-filter-predicate-builder", ".java");
    Path movedOutput = output.resolveSibling(output.getFileName() + ".moved");
    try {
      new org.apache.parquet.filter2.IncrementallyUpdatedFilterPredicateGenerator(output.toFile()).run();

      assertTrue(Files.size(output) > 1_000,
          "Generation must write a substantial Java class rather than an empty file");

      Files.move(output, movedOutput);
      assertTrue(Files.exists(movedOutput),
          "The generated file must remain usable after run closes its writer");
      assertTrue(Files.readString(movedOutput, StandardCharsets.UTF_8)
              .contains("public class IncrementallyUpdatedFilterPredicateBuilder"),
          "The moved output must contain the generated class");
    } finally {
      Files.deleteIfExists(output);
      Files.deleteIfExists(movedOutput);
    }
  }

  @Test
  void runIncludesNullHandlingForEqualityAndMembershipPredicates() throws IOException {
    Path output = Files.createTempFile("incrementally-updated-filter-predicate-builder", ".java");
    try {
      new org.apache.parquet.filter2.IncrementallyUpdatedFilterPredicateGenerator(output.toFile()).run();

      String source = Files.readString(output, StandardCharsets.UTF_8);

      assertTrue(source.contains("public void updateNull()"),
          "Generated value inspectors must define null handling");
      assertTrue(source.contains("final boolean containsNull = target.contains(null);"),
          "Generated membership inspectors must account for null membership values");
      assertTrue(source.contains("setResult(containsNull);"),
          "Generated In inspectors must use membership of null for null input");
      assertTrue(source.contains("setResult(!containsNull);"),
          "Generated NotIn inspectors must invert null membership");
      assertTrue(source.contains("setResult(false);"),
          "Generated inequality inspectors must reject null input");
    } finally {
      Files.deleteIfExists(output);
    }
  }

  private static void assertContainsAll(String source, String... requiredFragments) {
    for (String fragment : requiredFragments) {
      assertTrue(source.contains(fragment),
          "Generated source must contain: " + fragment);
    }
  }
}

