  @Test
  public void testRunGeneratesExpectedClassStructure() throws IOException {
    File outputFile = tempDir.resolve("IncrementallyUpdatedFilterPredicateBuilder.java").toFile();

    IncrementallyUpdatedFilterPredicateGenerator generator = new IncrementallyUpdatedFilterPredicateGenerator(outputFile);
    generator.run();

    assertTrue(outputFile.exists(), "Generated file should exist");

    String content = Files.readString(outputFile.toPath());

    // Check package declaration
    assertTrue(content.contains("package org.apache.parquet.filter2.recordlevel;"), 
        "Generated code should have correct package declaration");

    // Check class definition
    assertTrue(content.contains("public class IncrementallyUpdatedFilterPredicateBuilder extends IncrementallyUpdatedFilterPredicateBuilderBase"), 
        "Generated class should extend IncrementallyUpdatedFilterPredicateBuilderBase");

    // Check constructor
    assertTrue(content.contains("public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves)"), 
        "Generated class should have constructor accepting List<PrimitiveColumnIO>");
  }

